#nullable enable // autogenerated

using System.Collections.Generic;

namespace PVZEngine.Level
{
    public class ModifiableConveyorPool : IConveyorPool, IConveyorPatchTarget
    {
        public IConveyorPoolEntry Get(int index)
        {
            return modifiedPool[index];
        }
        public IConveyorPoolEntry? Find(NamespaceID id)
        {
            foreach (var entry in modifiedPool)
            {
                if (entry.ID == id)
                    return entry;
            }
            return null;
        }
        public int IndexOf(NamespaceID id)
        {
            return modifiedPool.FindIndex(e => e.ID == id);
        }
        public void UpdatePool(LevelEngine level)
        {
            UpdatePool(level.GetConveyorPool(), level.GetConveyorPoolPatches());
        }
        public void UpdatePool(IConveyorPoolEntry[]? levelPool, IConveyorPoolPatch[]? patches)
        {
            modifiedPool.Clear();
            if (levelPool != null)
            {
                foreach (var entry in levelPool)
                {
                    modifiedPool.Add(new ModifiableConveyorPoolEntry(entry));
                }
            }

            if (patches != null)
            {
                foreach (var patch in patches)
                {
                    patch.Patch(this);
                }
            }
        }
        public void AddEntry(NamespaceID id, int count, int minCount)
        {
            modifiedPool.Add(new ModifiableConveyorPoolEntry(id, count, minCount));
        }

        public void RemoveEntry(NamespaceID id)
        {
            var index = IndexOf(id);
            if (index >= 0)
            {
                modifiedPool.RemoveAt(index);
            }
        }

        public void SetEntryCount(NamespaceID id, int count)
        {
            var index = IndexOf(id);
            if (index >= 0)
            {
                var entry = modifiedPool[index];
                entry.Count = count;
                modifiedPool[index] = entry;
            }
        }

        public int GetEntryCount(NamespaceID id)
        {
            var index = IndexOf(id);
            if (index >= 0)
            {
                return modifiedPool[index].Count;
            }
            return 0;
        }

        public void SetEntryMinRefillCount(NamespaceID id, int count)
        {
            var index = IndexOf(id);
            if (index >= 0)
            {
                var entry = modifiedPool[index];
                entry.MinCount = count;
                modifiedPool[index] = entry;
            }
        }

        public int GetEntryMinRefillCount(NamespaceID id)
        {
            var index = IndexOf(id);
            if (index >= 0)
            {
                return modifiedPool[index].MinCount;
            }
            return 0;
        }
        public int Count => modifiedPool.Count;
        private readonly List<ModifiableConveyorPoolEntry> modifiedPool = new List<ModifiableConveyorPoolEntry>();
    }
}